from decimal import Decimal


def _numeric_line_no(value: object) -> Decimal:
    """Apply legacy numeric coercion: an empty value is numeric zero."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    surviving: list[tuple[str, Decimal, int, dict]] = []

    for input_index, row in enumerate(lines):
        if row.get("DEL_FLG", "") == "Y":
            continue

        order_id = str(row.get("ORD_ID", ""))
        original_line_no = _numeric_line_no(row.get("LINE_NO", ""))
        surviving.append((order_id, original_line_no, input_index, row))

    surviving.sort(key=lambda item: (item[0], item[1], item[2]))

    result: list[dict] = []
    current_order_id: str | None = None
    next_line_no = 0

    for order_id, _, _, row in surviving:
        if order_id != current_order_id:
            current_order_id = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        renumbered_row = dict(row)
        renumbered_row["LINE_NO"] = next_line_no
        result.append(renumbered_row)

    return result
